KG42.register("clusters-5d08e1ef02f5023bcb1a45da",{"id":"05-double_auction::v142-d-CL001","paper":"05-double_auction","label":"Historical price signals and conditional two-sided bidding","record":{"cluster_id":"v142-d-CL001","label":"Historical price signals and conditional two-sided bidding","market_meaning":"After selecting a bidding behavior, buyers and sellers submit sealed prices and electricity quantities; past transactions provide a reference for subsequent bids, and local electricity prices are used for initialization in the first round. Random bidding, preference-factor bidding, and game-theoretic bidding retain their respective conditions.","mechanism_ids":["v141-a-M01"],"market_types":["LEM"],"process_stages":["coordination","bidding"],"scope_disposition":"conditional","scope_explanation":"Only price signal generation and its use in bidding within M01 are assembled. The historical signal must correspond to the previous time period used for bidding; random bidding does not depend on this signal, and the seller's market assumption does not apply to all bidding situations.","assembly_status":"partial","boundary_rationale":"The boundary is defined by the information dependency through which reference prices enter two-sided bidding; clearing allocation, transaction pricing, and solving for strategy payoffs have distinct decision-making responsibilities and are not all incorporated merely because they are adjacent in the process.","chain_bindings":[{"chain_id":"v141-c-R005","ownership":"primary","role":"core","rationale":"Provides historical reference prices, first-round initialization, and the set of relative-price strategies."},{"chain_id":"v141-c-R001","ownership":"primary","role":"core","rationale":"Specifies buyers' sealed demand submissions and buyers' use of reference prices."},{"chain_id":"v141-c-R002","ownership":"primary","role":"core","rationale":"Specifies sellers' submissions and the conditional branches for different bidding behaviors; these branches do not take effect simultaneously."}],"connections":[{"connection_id":"v142-d-CL001-L01","from_chain_id":"v141-c-R005","to_chain_id":"v141-c-R001","kind":"quantity_interface","from_refs":["v141-c-R005::x::x_pseed"],"to_refs":["v141-c-R001::theta::v141-c-R001-theta-Pseed"],"evidence_ids":["v141-b-g01-ev-13","v141-b-g01-ev-14","v141-b-g01-ev-20","v141-b-g01-ev-22"],"rationale":"Reference prices generated from transaction history enter subsequent buyer bids; outputs are linked to fixed inputs only when the location, time period, and selected behavior correspond."},{"connection_id":"v142-d-CL001-L02","from_chain_id":"v141-c-R005","to_chain_id":"v141-c-R002","kind":"quantity_interface","from_refs":["v141-c-R005::x::x_pseed","v141-c-R005::phi::v141-c-R005-C002"],"to_refs":["v141-c-R002::theta::theta.P_seed","v141-c-R002::phi::v141-c-R002-C003"],"evidence_ids":["v141-b-g01-ev-13","v141-b-g02-E13","v141-b-g02-E14","v141-b-g02-E15","v141-b-g02-E16"],"rationale":"The same reference price and first-round initialization serve sellers' preference-factor or game-theoretic bidding; they do not extend to the random-bidding branch."},{"connection_id":"v142-d-CL001-L03","from_chain_id":"v141-c-R001","to_chain_id":"v141-c-R002","kind":"complementary_scope","from_refs":["v141-c-R001::phi::v141-c-R001-C001"],"to_refs":["v141-c-R002::phi::v141-c-R002-C004"],"evidence_ids":["v141-b-g01-ev-13"],"rationale":"The source text specifies buyers' and sellers' sealed submissions of prices and electricity quantities as complementary inputs to the same double auction; this does not imply that the two sides have the same prices or preferences."}],"object_mappings":[{"mapping_id":"v142-d-CL001-O01","kind":"same_quantity","member_refs":["v141-c-R005::x::x_pseed","v141-c-R001::theta::v141-c-R001-theta-Pseed","v141-c-R002::theta::theta.P_seed"],"canonical_ref":null,"display_policy":"linked_distinct","evidence_ids":["v141-b-g01-ev-14","v141-b-g01-ev-20","v141-b-g01-ev-22","v141-b-g02-E13"],"rationale":"Corresponds to the generation and use of the same historical reference price, maintaining the correspondence from the previous period to the next bidding period; each chain's variable or parameter role is retained."},{"mapping_id":"v142-d-CL001-O02","kind":"same_quantity","member_refs":["v141-c-R002::theta::theta.P_wholesale","v141-c-R005::theta::theta_Pwholesale"],"canonical_ref":null,"display_policy":"linked_distinct","evidence_ids":["v141-b-g01-ev-22","v141-b-g02-E15","v141-b-g02-E16"],"rationale":"Both chains use the wholesale electricity price at the same case-study location to initialize the signal; the numerical value in that case is not generalized."},{"mapping_id":"v142-d-CL001-O03","kind":"same_quantity","member_refs":["v141-c-R002::theta::theta.P_retail","v141-c-R005::theta::theta_Pretail"],"canonical_ref":null,"display_policy":"linked_distinct","evidence_ids":["v141-b-g01-ev-22","v141-b-g02-E15","v141-b-g02-E16"],"rationale":"Both chains use the average retail electricity price at the same case-study location, retaining their respective roles as initialization inputs."},{"mapping_id":"v142-d-CL001-O04","kind":"same_node","member_refs":["v141-c-R002::V::coordination.price_signal","v141-c-R005::V::coordination.price_signal"],"canonical_ref":"v141-c-R005::V::coordination.price_signal","display_policy":"single_representative","evidence_ids":["v141-b-g01-ev-13","v141-b-g02-E13","v141-b-g02-E14"],"rationale":"The same M01 reference-price coordination function occurs repeatedly in the generation chain and the seller-use chain; only a representative is selected for display."}],"gaps":[{"gap_id":"v142-d-CL001-G01","category":"scope_conflict","description":"The explanation of preference parameters in R001 lists different bidding behaviors side by side; the game formulation in R002 still needs to be matched separately to the sign restrictions for low and high preferences and to the 'same' strategy. Identical symbols do not justify equating different distributions, buying and selling directions, or strategy instances.","chain_ids":["v141-c-R001","v141-c-R002"],"object_refs":["v141-c-R001::theta::v141-c-R001-theta-delta","v141-c-R002::theta::theta.delta_i_preference_factor","v141-c-R002::theta::theta.delta_i_game_theoretic","v141-c-R002::phi::v141-c-R002-C002"],"evidence_ids":["v141-b-g01-ev-13","v141-b-g01-ev-14","v141-b-g02-E13"],"proposal_ids":[],"required_work":"B is to verify the behavioral branches, buying and selling directions, and sampling restrictions, after which C is to clarify the conditions under which the parameters apply; this round does not modify the distributions or supply missing parameters for the 'same' strategy."},{"gap_id":"v142-d-CL001-G02","category":"math_incomplete","description":"R005 does not specify the subsequent reference price when no trades occur or when the transaction-volume denominator is zero; the explicit definition, units, and transaction-by-transaction correspondence of T_m^P are also incomplete. First-round initialization cannot automatically serve as a fallback rule for any period with no trades.","chain_ids":["v141-c-R005"],"object_refs":["v141-c-R005::phi::v141-c-R005-C001","v141-c-R005::phi::v141-c-R005-C002","v141-c-R005::theta::theta_TmP"],"evidence_ids":["v141-b-g01-ev-12","v141-b-g01-ev-20","v141-b-g02-E15","v141-b-g03-e02"],"proposal_ids":[],"required_work":"Obtain the missing transaction-level price definitions, period correspondences, and basis for handling periods with no trades; until then, do not claim closure of the historical price update."},{"gap_id":"v142-d-CL001-G03","category":"upstream_missing","description":"The existing chains provide candidate prices and strategy sets, but do not contain a complete payoff matrix, strategy solution, or correspondence showing how the selected price enters the actual bid. The seller's-market branch cannot substitute for these steps either.","chain_ids":["v141-c-R001","v141-c-R002","v141-c-R005"],"object_refs":["v141-c-R001::x::v141-c-R001-x-chi","v141-c-R001::x::v141-c-R001-x-BP","v141-c-R002::phi::v141-c-R002-C006","v141-c-R005::x::x_strategy"],"evidence_ids":["v141-b-g01-ev-15","v141-b-g01-ev-17","v141-b-g02-E05","v141-b-g02-E06","v141-b-g02-E08","v141-b-g02-E09","v141-b-g02-E10"],"proposal_ids":["v141-b-g01-prop-04"],"required_work":"Keep the payoff-node proposal unapproved; upstream work is to complete the payoff, strategy-selection, and submission interfaces and verify the source text's explanations of dominant strategies and Nash equilibrium."},{"gap_id":"v142-d-CL001-G04","category":"ontology_extension","description":"The existing bidding-node definitions focus on electricity quantities, and no ontology decision has yet been made on the distinct semantics of price submission; R002 also lacks a separate object for the submitted electricity quantity.","chain_ids":["v141-c-R001","v141-c-R002"],"object_refs":["v141-c-R001::V::bidding.demand","v141-c-R002::V::bidding.supply","v141-c-R002::phi::v141-c-R002-C004"],"evidence_ids":["v141-b-g01-ev-01","v141-b-g01-ev-12","v141-b-g01-ev-13"],"proposal_ids":["v141-b-g01-prop-01"],"required_work":"Handle the price-submission proposal manually, and have C determine the seller's electricity-quantity object and its source; D does not insert nodes or fabricate object references."},{"gap_id":"v142-d-CL001-G05","category":"unverified_source","description":"All B texts cited by this cluster are UNREVIEWED candidates; the pricing behaviors, distributions, and historical signals have not passed independent source review.","chain_ids":["v141-c-R001","v141-c-R002","v141-c-R005"],"object_refs":[],"evidence_ids":["v141-b-g01-ev-13","v141-b-g01-ev-14","v141-b-g01-ev-20","v141-b-g01-ev-22","v141-b-g02-E12","v141-b-g02-E13","v141-b-g02-E14","v141-b-g02-E15","v141-b-g02-E16"],"proposal_ids":[],"required_work":"Subsequently verify the sources and C interpretations independently; eligibility as an experimental candidate does not change the existing source_status."}]},"rule_refs":["05-double_auction::v141-c-R005","05-double_auction::v141-c-R001","05-double_auction::v141-c-R002"],"unresolved_rule_refs":[],"node_ids":["COMP-60fa17e84f308f18","COMP-d3b88931c4051195","KG40-12aedc3eec573697","KG40-20f45ec4bdcbac06"]});
